import definitions from '../core/reflection-definitions.json' with {type:'json'};
export const registerReflection=(compiler,name)=>{if(!definitions[name.toLowerCase()])return false;for(const [key,definition]of Object.entries(definitions)){compiler.classes[key]=compiler.environment.classes[key]=definition.class;for(const [id,fn]of Object.entries(definition.functions))compiler.functions[id]={...fn,source:compiler.source};}return true;};
